package com.muxigame.city;
import java.util.*;
import net.minecraft.server.MinecraftServer;

/** Finite municipal pantry and seven-day food bridge. Rural private stocks are never public aid. */
public final class CityRelief {
 public static final class Policy {public int capacity=-1;public long bought,given,spent,lastPurchase=-1;public Map<UUID,Long> meals=new LinkedHashMap<>();}
 public static final class Unemployment {public boolean tracked;public long since=-1,workSeen;}
 static boolean applies(MinecraftServer s,UUID city){var town=CityTrade.get(s).state.towns.get(city);return town!=null&&town.model&&town.urban;}
 static Policy policy(MinecraftServer s,UUID city){var t=CityTrade.get(s);var p=t.state.relief.computeIfAbsent(city,k->new Policy());if(p.capacity<0){var d=RuralSettlement.get(s);int demand=d.state.families.values().stream().filter(f->f.city.equals(city)).mapToInt(f->RuralRules.demand(f,d.state.people)).sum();p.capacity=Math.min(4096,DataCityRules.foodReserve(demand,3));t.setDirty();}return p;}
 static boolean employed(MinecraftServer s,RuralRules.Person p,UUID city){if(p.role==RuralRules.Role.NONE||p.role==RuralRules.Role.VAGRANT)return false;var t=CityTrade.get(s);if(t.state.businesses.values().stream().anyMatch(b->p.id.equals(b.worker)&&b.closing))return false;return RuralSettlement.get(s).state.sites.values().stream().anyMatch(site->site.city.equals(city)&&p.id.equals(site.worker)&&RuralTools.available(s,site));}
 static void track(MinecraftServer s,UUID city){if(!applies(s,city))return;var d=RuralSettlement.get(s);var t=CityTrade.get(s);long now=d.state.simulationTicks;var c=CityData.get(s).require(city);for(var p:d.state.people.values()){if(p.dead||!city.equals(d.state.families.get(p.family).city))continue;boolean job=employed(s,p,city);var a=t.state.unemployment.computeIfAbsent(p.id,k->new Unemployment());if(!a.tracked){a.tracked=true;a.workSeen=p.totalWorkingTicks;a.since=job?-1:now;}else if(a.since<0){if(!job){a.since=now;a.workSeen=p.totalWorkingTicks;}}else if(job&&(p.totalWorkingTicks-a.workSeen>=1200||t.state.staffIncomeAt.getOrDefault(p.id,-1L)>a.since)){a.since=-1;a.workSeen=p.totalWorkingTicks;}else if(!job)a.workSeen=p.totalWorkingTicks;
   if(a.since>=0&&now-a.since>=7*24000L&&p.role==RuralRules.Role.NONE&&!FamilyLivelihood.home(c,d.state.families.get(p.family))){RuralSuccession.setRole(p,RuralRules.Role.VAGRANT);p.workStatus="连续失业七日且无合法住所，成为流民";d.log(p.name+"七日失业救济期满；没有住所");}
  }t.setDirty();d.setDirty();}
 static long budget(MinecraftServer s,UUID city){return Math.max(0,CityEconomy.get(s).balance(CityEconomy.treasury(city))-3*CityCurrency.payroll(s,city));}
 static int forecast(MinecraftServer s,UUID city){if(!applies(s,city))return 0;var t=CityTrade.get(s);int q=CityOpportunities.expectedBread(s,city);if(q>t.base(city,1))return 0;var c=CityData.get(s).require(city);return (int)Math.min(Math.min(Math.max(0,policy(s,city).capacity-c.works.resources.getOrDefault("minecraft:bread",0)),CityTrade.population(s,city)),budget(s,city)/q);}
 static int purchase(MinecraftServer s,UUID city){if(!applies(s,city))return 0;var d=RuralSettlement.get(s);if(Math.floorMod(d.state.simulationDay,24000)>=12000)return 0;var p=policy(s,city);long now=d.state.simulationTicks;if(p.lastPurchase>=0&&now-p.lastPurchase<3000)return 0;p.lastPurchase=now;var t=CityTrade.get(s);var c=CityData.get(s).require(city);int q=t.quote(s,city,1,now),got=0;if(q>t.base(city,1))return 0;int limit=Math.max(1,CityTrade.population(s,city)/4);for(var seller:t.sellers(city,1)){int before=c.works.resources.getOrDefault("minecraft:bread",0),n=(int)Math.min(Math.min(limit-got,Math.min(p.capacity-before,seller.listed[1].count)),budget(s,city)/q);if(n<=0)continue;if(!CityTrade.pay(s,CityEconomy.treasury(city),seller.account,n*(long)q,"PUBLIC_GRAIN_PURCHASE"))continue;long cost=seller.listed[1].take(n);var age=c.works.foodAges.computeIfAbsent("minecraft:bread",k->new FoodAge.State());age.ensure(before);age.add(n,seller.listed[1].removedAge.age());c.works.resources.put("minecraft:bread",before+n);seller.sales+=n*(long)q;seller.sold[1]+=n;t.profit(s,seller,n*q,cost);t.soldFrom(seller,1);p.bought+=n;p.spent+=n*(long)q;got+=n;if(got>=limit)break;}if(got>0){CityData.get(s).setDirty();t.setDirty();}return got;}
 static int give(MinecraftServer s,RuralRules.Family family){if(!applies(s,family.city))return 0;var t=CityTrade.get(s);var d=RuralSettlement.get(s);long now=d.state.simulationTicks;var policy=policy(s,family.city);if(Objects.equals(policy.meals.get(family.id),now))return 0;policy.meals.put(family.id,now);int eligible=0;for(var p:RuralRules.members(family,d.state.people)){var a=t.state.unemployment.get(p.id);if(a!=null&&a.since>=0&&now-a.since<7*24000L)eligible+=p.meal();}if(eligible==0)return 0;var stores=d.stocks(family.id);int ready=RuralRules.count(stores,true)+stores.stream().mapToInt(v->Arrays.stream(v.cooked).sum()).sum(),missing=Math.max(0,RuralRules.demand(family,d.state.people)-ready);var c=CityData.get(s).require(family.city);int before=c.works.resources.getOrDefault("minecraft:bread",0),available=Math.max(0,before-(policy.capacity+9)/10);int n=Math.min(Math.min(eligible,missing),Math.min(available,RuralRules.capacity(stores)));if(n<=0)return 0;var age=c.works.foodAges.computeIfAbsent("minecraft:bread",k->new FoodAge.State());age.ensure(before);var portion=age.take(n);c.works.resources.put("minecraft:bread",before-n);CityEconomy.require(FoodMoves.add(stores,1,n,portion.age())==n,"Public food transfer capacity changed");policy.given+=n;t.setDirty();d.setDirty();CityData.get(s).setDirty();return n;}
 static void shift(MinecraftServer s,UUID city,long shift){var t=CityTrade.get(s);var p=t.state.relief.get(city);if(p!=null){if(p.lastPurchase>=0)p.lastPurchase+=shift;p.meals.replaceAll((id,time)->time+shift);}var d=RuralSettlement.get(s);for(var a:t.state.unemployment.entrySet()){var person=d.state.people.get(a.getKey());if(person!=null&&city.equals(d.state.families.get(person.family).city)&&a.getValue().since>=0)a.getValue().since+=shift;}}
}
